import { test, expect } from '@playwright/test';

test.describe('Notification Management', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/notifications');
    await page.waitForSelector('text=Notifications'); // Ensure the notifications page is loaded
  });

  test('should delete a single notification', async ({ page }) => {
    const notificationToDelete = await page.getByText('Sample Notification to Delete');

    // Ensure the notification exists before attempting to delete
    await expect(notificationToDelete).toBeVisible();

    // Click the delete button associated with the notification
    await notificationToDelete.locator('button', { hasText: 'Delete' }).click();

    // Confirm deletion in the confirmation dialog
    await page.getByRole('button', { name: 'Confirm' }).click();

    // Verify the notification is no longer visible
    await expect(notificationToDelete).not.toBeVisible();
  });

  test('should not delete a notification if cancel is clicked', async ({ page }) => {
    const notificationToCancelDelete = await page.getByText('Sample Notification to Cancel Delete');

    // Ensure the notification exists before attempting to delete
    await expect(notificationToCancelDelete).toBeVisible();

    // Click the delete button associated with the notification
    await notificationToCancelDelete.locator('button', { hasText: 'Delete' }).click();

    // Cancel deletion in the confirmation dialog
    await page.getByRole('button', { name: 'Cancel' }).click();

    // Verify the notification is still visible
    await expect(notificationToCancelDelete).toBeVisible();
  });
});
